using System.Runtime.CompilerServices;
using DeskCanvas.App.Services;
internal static class V18VisualContractTestsAccepted
{
 [ModuleInitializer]internal static void Run(){var graph=new SmoothedNetworkGraph();for(var i=0;i<35;i++)graph.Add(i*500);if(graph.Count!=30||graph.Scale<17000)throw new InvalidOperationException("30-sample immediate scale failed");graph.Add(0);graph.Add(0);graph.Add(0);var held=graph.Scale;graph.Add(0);if(graph.Scale>=held)throw new InvalidOperationException("three sample hold/twelve percent decay failed");var start=graph.Advance(TimeSpan.Zero);var middle=graph.Advance(TimeSpan.FromMilliseconds(350));graph.Advance(TimeSpan.FromMilliseconds(350));if(start.SequenceEqual(middle)||graph.IsAnimating)throw new InvalidOperationException("700ms easeout/timer stop failed");graph.Stop();if(graph.IsAnimating)throw new InvalidOperationException("hidden lifetime failed");var curve=ArtworkPaletteMathV18.Bezier([new NetworkGraphPoint(0,-1),new NetworkGraphPoint(20,19)]);if(curve[0].Y1<0||curve[0].Y2>16)throw new InvalidOperationException("bezier clamp failed");var neon=Enumerable.Repeat(new PaletteRgb(15,25,30),40).Concat(Enumerable.Repeat(new PaletteRgb(0,255,0),6)).ToArray();if(!ArtworkPaletteMathV18.TryResolve(neon,out var p)||p.Accent.G==255||p.SurfaceA.Luminance>.23||ArtworkPaletteMathV18.ContrastRatio(p.SurfaceA,p.Foreground)<4.5)throw new InvalidOperationException("neon palette failed");if(ArtworkPaletteMathV18.TryResolve(Enumerable.Repeat(new PaletteRgb(88,88,88),30).ToArray(),out _))throw new InvalidOperationException("monochrome fallback failed");const double card=360,reserve=35,trio=138;var left=reserve+(card-2*reserve-trio)/2;if(Math.Abs(left+trio/2-card/2)>.5)throw new InvalidOperationException("center grid geometry failed");Console.WriteLine("PASS v1.8 palette graph and centered transport");}
}
